  FILTER (CONTAINS(str(?label), "ZN_2") || CONTAINS(str(?label), "ZN_6"))
}

SELECT ?p ?label WHERE {
  ?p rdfs:label ?label .
  FILTER (CONTAINS(LCASE(str(?label)), "perimeter") || CONTAINS(LCASE(str(?label)), "datacenter"))
} LIMIT 50

SELECT ?z ?label ?ts WHERE {
  ?z a brick:Zone .
  ?z rdfs:label ?label .
  FILTER (?label = "Perimeter_top_ZN_2" || ?label = "DataCenter_top_ZN_6")
  OPTIONAL { ?z ref:hasTimeseriesId ?ts }
}

